159	  @SuppressWarnings("deprecation")
160	  public void runLocalization(final InetSocketAddress nmAddr)
161	      throws IOException, InterruptedException {
162	    // load credentials
163	    initDirs(conf, user, appId, lfs, localDirs);
164	    final Credentials creds = new Credentials();
165	    DataInputStream credFile = null;
166	    try {
167	      // assume credentials in cwd
168	      // TODO: Fix
169	      Path tokenPath = new Path(tokenFileName);
170	      credFile = lfs.open(tokenPath);
171	      creds.readTokenStorageStream(credFile);
172	      // Explicitly deleting token file.
173	      lfs.delete(tokenPath, false);      
174	    } finally  {
175	      if (credFile != null) {
176	        credFile.close();
177	      }
178	    }
179	    // create localizer context
180	    UserGroupInformation remoteUser =
181	      UserGroupInformation.createRemoteUser(user);
182	    remoteUser.addToken(creds.getToken(LocalizerTokenIdentifier.KIND));
183	    final LocalizationProtocol nodeManager =
184	        remoteUser.doAs(new PrivilegedAction<LocalizationProtocol>() {
185	          @Override
186	          public LocalizationProtocol run() {
187	            return getProxy(nmAddr);
188	          }
189	        });
190	
191	    // create user context
192	    UserGroupInformation ugi =
193	      UserGroupInformation.createRemoteUser(user);
194	    for (Token<? extends TokenIdentifier> token : creds.getAllTokens()) {
195	      ugi.addToken(token);
196	    }
197	
198	    ExecutorService exec = null;
199	    try {
200	      exec = createDownloadThreadPool();
201	      CompletionService<Path> ecs = createCompletionService(exec);
202	      localizeFiles(nodeManager, ecs, ugi);
203	    } catch (Throwable e) {
204	      throw new IOException(e);
205	    } finally {
206	      try {
207	        if (exec != null) {
208	          exec.shutdown();
209	          destroyShellProcesses(getAllShells());
210	          exec.awaitTermination(10, TimeUnit.SECONDS);
211	        }
212	        LocalDirAllocator.removeContext(appCacheDirContextName);
213	      } finally {
214	        closeFileSystems(ugi);
215	      }
216	    }
217	  }
