252	  Callable<Path> download(Path destDirPath, LocalResource rsrc,
253	      UserGroupInformation ugi) throws IOException {
254	    // For private localization FsDownload creates folder in destDirPath. Parent
255	    // directories till user filecache folder is created here.
256	    if (rsrc.getVisibility() == LocalResourceVisibility.PRIVATE) {
257	      createParentDirs(destDirPath);
258	    }
259	    diskValidator
260	        .checkStatus(new File(destDirPath.getParent().toUri().getRawPath()));
261	    return new FSDownloadWrapper(lfs, ugi, conf, destDirPath, rsrc);
262	  }
