264	  private void createParentDirs(Path destDirPath) throws IOException {
265	    Path parent = destDirPath.getParent();
266	    Path cacheRoot = LocalCacheDirectoryManager.getCacheDirectoryRoot(parent);
267	    Stack<Path> dirs = new Stack<Path>();
268	    while (!parent.equals(cacheRoot)) {
269	      dirs.push(parent);
270	      parent = parent.getParent();
271	    }
272	    // Create directories with user cache permission
273	    while (!dirs.isEmpty()) {
274	      createDir(lfs, dirs.pop(), USERCACHE_FOLDER_PERMS);
275	    }
276	  }
