278	  static long getEstimatedSize(LocalResource rsrc) {
279	    if (rsrc.getSize() < 0) {
280	      return -1;
281	    }
282	    switch (rsrc.getType()) {
283	      case ARCHIVE:
284	      case PATTERN:
285	        return 5 * rsrc.getSize();
286	      case FILE:
287	      default:
288	        return rsrc.getSize();
289	    }
290	  }
