304	  protected void localizeFiles(LocalizationProtocol nodemanager,
305	      CompletionService<Path> cs, UserGroupInformation ugi)
306	      throws IOException, YarnException {
307	    while (true) {
308	      try {
309	        LocalizerStatus status = createStatus();
310	        LocalizerHeartbeatResponse response = nodemanager.heartbeat(status);
311	        switch (response.getLocalizerAction()) {
312	        case LIVE:
313	          List<ResourceLocalizationSpec> newRsrcs = response.getResourceSpecs();
314	          for (ResourceLocalizationSpec newRsrc : newRsrcs) {
315	            if (!pendingResources.containsKey(newRsrc.getResource())) {
316	              pendingResources.put(newRsrc.getResource(), cs.submit(download(
317	                new Path(newRsrc.getDestinationDirectory().getFile()),
318	                newRsrc.getResource(), ugi)));
319	            }
320	          }
321	          break;
322	        case DIE:
323	          // killall running localizations
324	          for (Future<Path> pending : pendingResources.values()) {
325	            pending.cancel(true);
326	          }
327	          status = createStatus();
328	          // ignore response while dying.
329	          try {
330	            nodemanager.heartbeat(status);
331	          } catch (YarnException e) {
332	            // Cannot do anything about this during death stage, let's just log
333	            // it.
334	            e.printStackTrace(System.out);
335	            LOG.error("Heartbeat failed while dying: ", e);
336	          }
337	          return;
338	        }
339	        cs.poll(1000, TimeUnit.MILLISECONDS);
340	      } catch (InterruptedException e) {
341	        return;
342	      } catch (YarnException e) {
343	        // TODO cleanup
344	        throw e;
345	      }
346	    }
347	  }
