349	  /**
350	   * Create the payload for the HeartBeat. Mainly the list of
351	   * {@link LocalResourceStatus}es
352	   * 
353	   * @return a {@link LocalizerStatus} that can be sent via heartbeat.
354	   * @throws InterruptedException
355	   */
356	  private LocalizerStatus createStatus() throws InterruptedException {
357	    final List<LocalResourceStatus> currentResources =
358	      new ArrayList<LocalResourceStatus>();
359	    // TODO: Synchronization??
360	    for (Iterator<Entry<LocalResource, Future<Path>>> i =
361	        pendingResources.entrySet().iterator(); i.hasNext();) {
362	      Entry<LocalResource, Future<Path>> mapEntry = i.next();
363	      LocalResourceStatus stat =
364	        recordFactory.newRecordInstance(LocalResourceStatus.class);
365	      stat.setResource(mapEntry.getKey());
366	      Future<Path> fPath = mapEntry.getValue();
367	      if (fPath.isDone()) {
368	        try {
369	          Path localPath = fPath.get();
370	          stat.setLocalPath(
371	              URL.fromPath(localPath));
372	          stat.setLocalSize(
373	              FileUtil.getDU(new File(localPath.getParent().toUri())));
374	          stat.setStatus(ResourceStatusType.FETCH_SUCCESS);
375	        } catch (ExecutionException e) {
376	          stat.setStatus(ResourceStatusType.FETCH_FAILURE);
377	          stat.setException(SerializedException.newInstance(e.getCause()));
378	        } catch (CancellationException e) {
379	          stat.setStatus(ResourceStatusType.FETCH_FAILURE);
380	          stat.setException(SerializedException.newInstance(e));
381	        }
382	        // TODO shouldn't remove until ACK
383	        i.remove();
384	      } else {
385	        stat.setStatus(ResourceStatusType.FETCH_PENDING);
386	      }
387	      currentResources.add(stat);
388	    }
389	    LocalizerStatus status =
390	      recordFactory.newRecordInstance(LocalizerStatus.class);
391	    status.setLocalizerId(localizerId);
392	    status.addAllResources(currentResources);
393	    return status;
394	  }
