448	  public static void main(String[] argv) throws Throwable {
449	    Thread.setDefaultUncaughtExceptionHandler(new YarnUncaughtExceptionHandler());
450	    int nRet = 0;
451	    // usage: $0 user appId locId host port app_log_dir user_dir [user_dir]*
452	    // let $x = $x/usercache for $local.dir
453	    // MKDIR $x/$user/appcache/$appid
454	    // MKDIR $x/$user/appcache/$appid/output
455	    // MKDIR $x/$user/appcache/$appid/filecache
456	    // LOAD $x/$user/appcache/$appid/appTokens
457	    try {
458	      String user = argv[0];
459	      String appId = argv[1];
460	      String locId = argv[2];
461	      InetSocketAddress nmAddr =
462	          new InetSocketAddress(argv[3], Integer.parseInt(argv[4]));
463	      String tokenFileName = argv[5];
464	      String[] sLocaldirs = Arrays.copyOfRange(argv, 6, argv.length);
465	      ArrayList<Path> localDirs = new ArrayList<>(sLocaldirs.length);
466	      for (String sLocaldir : sLocaldirs) {
467	        localDirs.add(new Path(sLocaldir));
468	      }
469	
470	      final String uid =
471	          UserGroupInformation.getCurrentUser().getShortUserName();
472	      if (!user.equals(uid)) {
473	        // TODO: fail localization
474	        LOG.warn("Localization running as " + uid + " not " + user);
475	      }
476	
477	      ContainerLocalizer localizer = new ContainerLocalizer(
478	          FileContext.getLocalFSFileContext(), user,
479	              appId, locId, tokenFileName, localDirs,
480	              RecordFactoryProvider.getRecordFactory(null));
481	      localizer.runLocalization(nmAddr);
482	    } catch (Throwable e) {
483	      // Print traces to stdout so that they can be logged by the NM address
484	      // space in both DefaultCE and LCE cases
485	      e.printStackTrace(System.out);
486	      LOG.error("Exception in main:", e);
487	      nRet = -1;
488	    } finally {
489	      System.exit(nRet);
490	    }
491	  }
