493	  private static void initDirs(Configuration conf, String user, String appId,
494	      FileContext lfs, List<Path> localDirs) throws IOException {
495	    if (null == localDirs || 0 == localDirs.size()) {
496	      throw new IOException("Cannot initialize without local dirs");
497	    }
498	    String[] appsFileCacheDirs = new String[localDirs.size()];
499	    String[] usersFileCacheDirs = new String[localDirs.size()];
500	    for (int i = 0, n = localDirs.size(); i < n; ++i) {
501	      // $x/usercache/$user
502	      Path base = lfs.makeQualified(
503	          new Path(new Path(localDirs.get(i), USERCACHE), user));
504	      // $x/usercache/$user/filecache
505	      Path userFileCacheDir = new Path(base, FILECACHE);
506	      usersFileCacheDirs[i] = userFileCacheDir.toString();
507	      createDir(lfs, userFileCacheDir, FILECACHE_PERMS);
508	      // $x/usercache/$user/appcache/$appId
509	      Path appBase = new Path(base, new Path(APPCACHE, appId));
510	      // $x/usercache/$user/appcache/$appId/filecache
511	      Path appFileCacheDir = new Path(appBase, FILECACHE);
512	      appsFileCacheDirs[i] = appFileCacheDir.toString();
513	      createDir(lfs, appFileCacheDir, FILECACHE_PERMS);
514	    }
515	    conf.setStrings(String.format(APPCACHE_CTXT_FMT, appId), appsFileCacheDirs);
516	    conf.setStrings(String.format(USERCACHE_CTXT_FMT, user), usersFileCacheDirs);
517	  }
