519	  private static void createDir(FileContext lfs, Path dirPath,
520	      FsPermission perms) throws IOException {
521	    lfs.mkdir(dirPath, perms, false);
522	    if (!perms.equals(perms.applyUMask(lfs.getUMask()))) {
523	      lfs.setPermission(dirPath, perms);
524	    }
525	  }
